var s=[{title:`Apprendre le mouvement`,text:`Tenez-vous avec les genoux souples. Poussez les hanches vers l’arrière comme pour fermer une portière de voiture avec elles, et laissez le torse basculer vers l’avant pendant que votre dos reste dans une position confortable et contrôlée. Arrêtez-vous quand les ischio-jambiers limitent le mouvement ou que le tronc ne reste plus contrôlé, puis poussez les hanches vers l’avant pour vous relever. Vous travaillez le mouvement de la hanche, donc toucher le sol n’est pas l’objectif.`},{title:`Charnière et squat`,text:`Les deux mouvements utilisent les hanches et les genoux, avec un accent différent. Dans un squat, les genoux fléchissent généralement davantage et le torse reste plus droit. Dans un soulevé de terre roumain, les genoux fléchissent un peu et les hanches reculent davantage, ce qui sollicite plus l’arrière du corps. Un pont fessier travaille l’extension de la hanche avec le torse soutenu et constitue parfois un point de départ plus facile.`},{title:`Exercices pédagogiques`,text:`Pour le contact au mur, placez-vous à un petit pas d’un mur et poussez les hanches vers l’arrière jusqu’à ce qu’elles le touchent. Un bâton léger tenu le long de la tête, du haut du dos et du bassin peut vous indiquer quand votre colonne bouge beaucoup. Utilisez ces exercices pour apprendre, et ne forcez pas une posture rigide à cause d’eux.`},{title:`Progression et erreurs`,text:`Commencez avec des répétitions sans charge, puis passez à un soulevé de terre léger au kettlebell ou à un soulevé de terre roumain aux haltères. Gardez le poids près du corps et utilisez une amplitude que vous contrôlez. Fléchir trop les genoux transforme la levée en squat, et viser une profondeur imposée peut déplacer le mouvement vers votre dos. Les swings demandent plus d’habileté qu’une charnière lente.`},{title:`Avec TrainUp`,text:`Votre programme comprend des exercices de charnière adaptés à votre équipement et à votre objectif. Si l’équilibre ou un dos sensible rend les charnières chargées difficiles, une variante avec appui ou un pont de hanche est une option, et vous pouvez noter une limite du dos dans Profil. Si la douleur persiste, consultez un médecin ou un kinésithérapeute au lieu de monter votre propre programme de rééducation.`}];var r=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACE : technique du swing au kettlebell à deux mains`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`NSCA : sécurité et fondamentaux du renforcement`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var n={sections:s,sources:r};export{n as default,s as sections,r as sources};